// NHL player names, first-name + last-name only. 8735 unique names.
// Every player who has appeared in an NHL game, from the league's first season
// (1917-18) through the 2025-26 season. Players who appeared only in the WHA
// (1972-79) are not included.
// Each entry also includes lastYear: the START year of the player's final NHL
// season (e.g. 2002 means 2002-03), the same convention as the NBA file. It is
// used for the "guess an older player" scoring bonus.
//
// Sources:
//  1. 1917-18 through 2017-18: the Hockey Databank (Hockey Database v13.0,
//     July 2018; https://github.com/rippinrobr/hockey-databank). 7671 names.
//     "The information used herein was obtained free of charge from and is
//     copyrighted by the Hockey Databank project. For more information about the
//     Hockey Databank project please visit
//     http://sports.groups.yahoo.com/group/hockey-databank"
//     (The Databank license requires that statement to be displayed prominently
//     in the finished product.)
//  2. 2018-19 through 2025-26: per-game NHL box scores from the sportsdataverse
//     fastRhockey-nhl-data repository (https://github.com/sportsdataverse/fastRhockey-nhl-data,
//     MIT license; data sourced from the NHL API). 1064 names.
// For the roughly 2,200 players active in both sources (2009-10 to 2017-18), the
// spelling and lastYear come from the NHL API data; this changed the spelling for
// 86 of them (e.g. "Alexander Steen", not "Alex Steen"). Everyone else
// uses the Databank spelling, which has no accent marks. Where two players share a name,
// the entry uses whichever earns the smaller bonus (ties: the more recent player).
//
// Entries with an initials field have a multi-word last name (e.g. "Martin St. Louis"
// -> "MS", "Michael Del Zotto" -> "MD"), which the game's default (first word + last
// word of fullName) would get wrong. The initials are the first letter of the first word
// and the first letter of the whole last name, from the source data's separate last-name
// field (used only where it is a proper trailing part of the name). The game uses this
// field when present.
//
// Compiled for use in "Daily Duograms" — Copyright © 2026 UVM87 Games.
// Works in both the browser (var athletes) and Node (module.exports).

